-- Recovered from the production migration ledger for deterministic rebuilds.
create or replace function public.tedvio_my_admin_role() returns text language sql stable security definer set search_path=public as $$ select r.role from public.tedvio_admin_roles r where lower(r.email)=lower(coalesce(auth.jwt()->>'email','')) limit 1 $$; grant execute on function public.tedvio_my_admin_role() to authenticated; create or replace function public.tedvio_admin_metrics() returns jsonb language sql stable security definer set search_path=public as $$ select case when public.tedvio_my_admin_role()='admin' then jsonb_build_object('universities',(select count(*) from public.v2_universities),'programs',(select count(*) from public.v2_programs),'groups',(select count(*) from public.v2_groups),'sessions',(select count(*) from public.v2_sessions)) else null end $$; grant execute on function public.tedvio_admin_metrics() to authenticated;

